const K=0.5,R=0.16,HZ=2,MAXS=200,SC=4,X0=0.6,Z0=1.6;
const rand=n=>{const s=Math.sin(n*12.9898+78.233)*43758.5453;return s-Math.floor(s)};
const gauss=n=>Math.sqrt(-2*Math.log(Math.max(1e-9,rand(n))))*Math.cos(2*Math.PI*rand(n+0.37));
const loss=(S,x,z)=>0.5*(z*z+S*x*x);
const hx=S=>2/Math.sqrt(S);
const off=(s,i)=>Math.abs(s.x)>hx(i.stretch)||Math.abs(s.z)>HZ;
const over=(s,i)=>off(s,i)||s.step>=MAXS;
function noisy(s,i,seed){const k=seed*7919+s.step*2+1,n=i.noise;return[i.stretch*s.x+n*gauss(k),s.z+n*gauss(k+0.5)]}
const word=(s,i)=>off(s,i)?'diverged':s.step>=MAXS?(loss(i.stretch,s.x,s.z)<0.05?'converged':'stopped'):s.on?'running':'paused';
function adv(s,i,seed){if(over(s,i))return{...s,on:false};const[g,h]=noisy(s,i,seed),x=s.x-i.learningRate*g,z=s.z-i.learningRate*h,step=s.step+1;return{...s,x,z,step,path:step%2===0?s.path.concat([[x,z]]).slice(-100):s.path}}
const fresh=x=>({x,z:Z0,step:0,on:false,path:[[x,Z0]]});
export function initialState(){return fresh(X0)}
export function reduce({state:s,event:e,inputs:i,seed}){
if(e.type==='step')return s.on?adv(s,i,seed):s;
if(e.type==='action'){
if(e.action==='run')return over(s,i)?s:{...s,on:true};
if(e.action==='pause')return{...s,on:false};
if(e.action==='stepOnce')return adv({...s,on:false},i,seed);
if(e.action==='clearTrail')return{...s,path:[[s.x,s.z]]};
return s}
if(e.type.startsWith('drag')&&e.node==='ball'&&!s.on)return fresh(Math.max(-0.85,Math.min(0.85,e.value)));
return s}
function aim(dx,dz,shown){const v=Math.hypot(dx,dz),h=Math.SQRT1_2;return shown&&v>1e-6?{visible:true,quaternion:[dz/v*h,0,-dx/v*h,h],scale:[1,v*SC,1]}:{visible:false}}
export function evaluate({inputs:i,state,seed}){
const s=state||initialState(),S=i.stretch,lr=i.learningRate,L=loss(S,s.x,s.z),live=!over(s,i),g=noisy(s,i,seed),m=hx(S);
const lift=p=>[Math.max(-m,Math.min(m,p[0])),Math.min(K*loss(S,p[0],p[1]),2)+0.02,Math.max(-HZ,Math.min(HZ,p[1]))];
return{nodes:{
bowl:{scale:[1/Math.sqrt(S),1,1]},
ball:{position:[s.x,K*L+R,s.z]},
stepArrow:aim(-lr*g[0],-lr*g[1],live),
downArrow:aim(-lr*S*s.x,-lr*s.z,live),
trail:{points:s.path.map(lift)}},
readouts:{loss:L,steps:s.step,slope:Math.hypot(S*s.x,s.z),status:word(s,i)}}}

